def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev = 0
    desperate_opp = 0
    rich_opp = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 1.5:
                rich_opp += 1
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = prev.get('bid', 0)
                prev_bids.append(b)
                if b >= DAILY_SALARY * 0.9:
                    strong_prev += 1

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.25))

    slots = max(1, int(supply / WATER_REQ))
    competitors = len(alive) + 1
    scarcity = competitors - slots

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    base = DAILY_SALARY * 0.42

    if slots >= competitors:
        base = DAILY_SALARY * 0.18
    elif slots == competitors - 1:
        base = DAILY_SALARY * 0.48
    else:
        base = DAILY_SALARY * 0.62

    if supply <= 16:
        base += 10
    elif supply >= 23:
        base -= 8

    if max_prev >= 120:
        base += 6
    elif max_prev >= 90:
        base += 10
    elif max_prev <= 40 and prev_bids:
        base -= 5

    if avg_prev >= 80:
        base += 4

    if strong_prev >= 2:
        base += 6
    if desperate_opp >= 2:
        base += 5
    if rich_opp == 0:
        base -= 4

    if hp <= 2 or no_water_days >= 1:
        base = max(base, DAILY_SALARY * 0.9)
    elif hp <= 4:
        base = max(base, DAILY_SALARY * 0.68)
    elif hp >= 8 and supply >= 22:
        base -= 6

    if day >= 8 and hp > 4:
        base -= 4

    reserve = 0.0
    if hp > 4:
        reserve = DAILY_SALARY * 0.35
    affordable = max(0.0, budget - reserve)
    bid = min(base, budget)
    if affordable > 0:
        bid = min(bid, max(affordable, min(base, budget)))

    if hp <= 2 or no_water_days >= 1:
        bid = min(budget, max(bid, DAILY_SALARY * 0.9))

    if bid < 0:
        bid = 0.0
    return float(round(min(bid, budget), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o is not None and o.get('alive', False):
            alive.append(o)

    if not alive:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Pull yesterday bids from previous_trace only
    prev_bids = []
    for o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Identify if Cindy was applying strong pressure yesterday
    cindy_pressure = 0.0
    for oid, o in opponents_status.items():
        if oid == 'Cindy' and o is not None and o.get('alive', False):
            prev = o.get('previous_trace', {}) or {}
            b = prev.get('bid', None)
            if b is not None:
                try:
                    cindy_pressure = float(b)
                except Exception:
                    cindy_pressure = 0.0

    # Supply pressure: more supply => less need to overbid
    # Use int() for any index-like operations (none here), but keep logic numeric.
    supply_factor = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_factor = 0.5
    supply_factor = max(0.0, min(1.0, supply_factor))

    # Core bid target
    # If Cindy pushed hard yesterday, we bid enough to not lose the water entirely.
    # Otherwise bid a competitive mid value.
    if cindy_pressure >= DAILY_SALARY * 1.35 or highest_prev_bid >= DAILY_SALARY * 1.2:
        # When opponents likely spend, our hp/no-water days determine whether to match more.
        if my_hp <= 2 or my_no_water_days >= 2:
            target = DAILY_SALARY * (0.95 - 0.25 * supply_factor)
        else:
            target = DAILY_SALARY * (0.65 - 0.15 * supply_factor)
        # Slightly undercut relative to their pressure to avoid waste
        target = min(target, cindy_pressure * 0.98 if cindy_pressure > 0 else target)
    else:
        if my_hp <= 2 or my_no_water_days >= 2:
            target = DAILY_SALARY * (0.85 - 0.2 * supply_factor)
        else:
            target = DAILY_SALARY * (0.55 - 0.1 * supply_factor)

    # Ensure we don't bid more than we can afford
    bid = max(0.0, min(my_budget, target))

    # If budget is extremely low, bid whatever small amount still helps
    if my_budget <= 1.0:
        return my_budget

    # Add a small deterministic nudge by day to break ties
    nudge = ((int(day) % 7) - 3) * 0.5
    bid = bid + nudge
    bid = max(0.0, min(my_budget, bid))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    current_bid = DAILY_SALARY * 0.65

    # 1. Adjust based on my HP (survival priority)
    if my_status['hp'] <= 2:
        current_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        current_bid = DAILY_SALARY * 0.85
    elif my_status['hp'] <= 6:
        current_bid = DAILY_SALARY * 0.75

    # 2. Adjust based on supply (resource availability)
    supply = day_context['supply']
    if supply <= WATER_REQ + 2:
        current_bid *= 1.15
    elif supply >= MAX_SUPPLY - 2:
        current_bid *= 0.85

    # 3. React to yesterday's opponent bids (competition pressure)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        if max_yesterday_bid >= DAILY_SALARY * 0.8:
            current_bid = max(current_bid, max_yesterday_bid + 5)
        elif max_yesterday_bid >= DAILY_SALARY * 0.6:
            current_bid = max(current_bid, max_yesterday_bid + 2)

    # 4. Adjust for game phase (early vs. late game)
    day = day_context['day']
    if day >= EPISODE_DAYS - 2:
        current_bid *= 1.1
    elif day <= 2 and my_status['hp'] > 6:
        current_bid *= 0.9

    final_bid = min(my_status['budget'], current_bid)
    final_bid = max(1.0, final_bid)

    return final_bid

